# Automatic broadcasting and adaptive execution are off, so only your hints decide the plan.
spark.conf.set("spark.sql.adaptive.enabled", False)
spark.conf.set("spark.sql.autoBroadcastJoinThreshold", -1)


def uses_broadcast(df):
    # True when the physical plan uses a broadcast hash join.
    return "BroadcastHashJoin" in df._jdf.queryExecution().executedPlan().toString()


